package org.example.saildroid.camerasurface;
import android.app.*;import android.content.pm.PackageManager;import android.graphics.*;import android.hardware.Camera;import android.os.*;import android.view.*;import android.widget.*;
public final class MainActivity extends Activity implements SurfaceHolder.Callback {
 private Camera camera;private SurfaceView texture;private boolean ready,permission;private int callbacks;private boolean captured;
 @Override public void onCreate(Bundle state){super.onCreate(state);android.app.admin.DevicePolicyManager policy=(android.app.admin.DevicePolicyManager)getSystemService(DEVICE_POLICY_SERVICE);if(policy==null||policy.getCameraDisabled(null))throw new AssertionError("Unmanaged camera policy query failed");System.err.println("SDCAMERA_PROBE=admin_policy_ready|disabled=false");int count=Camera.getNumberOfCameras();if(count!=2)throw new AssertionError("Physical camera count differs");for(int i=0;i<count;i++){Camera.CameraInfo info=new Camera.CameraInfo();Camera.getCameraInfo(i,info);System.err.println("SDCAMERA_PROBE=info|id="+i+"|facing="+info.facing+"|orientation="+info.orientation);}
  permission=checkSelfPermission("android.permission.CAMERA")==PackageManager.PERMISSION_GRANTED;
  if(!permission){try{camera=Camera.open(0);throw new AssertionError("Camera opened before permission");}catch(SecurityException expected){System.err.println("SDCAMERA_PROBE=permission_denied_before_prompt");}}
  texture=new SurfaceView(this);texture.getHolder().addCallback(this);setContentView(texture);
  if(!permission)new Handler().postDelayed(()->requestPermissions(new String[]{"android.permission.CAMERA"},81),500);
 }
 @Override public void onRequestPermissionsResult(int code,String[] names,int[] grants){if(code!=81||grants.length!=1||grants[0]!=PackageManager.PERMISSION_GRANTED)throw new AssertionError("Camera permission was not granted");permission=true;System.err.println("SDCAMERA_PROBE=permission_granted");start();}
 @Override public void surfaceCreated(SurfaceHolder holder){ready=true;System.err.println("SDCAMERA_PROBE=surface_holder_ready");start();}
 private void start(){if(!ready||!permission||camera!=null)return;try{camera=Camera.open(0);Camera.Parameters p=camera.getParameters();p.setPreviewSize(640,480);p.setPreviewFormat(android.graphics.ImageFormat.NV21);p.setPictureSize(640,480);camera.setParameters(p);camera.setDisplayOrientation(90);camera.setPreviewDisplay(texture.getHolder());camera.setErrorCallback((error,c)->{throw new AssertionError("Physical camera error "+error);});camera.setPreviewCallbackWithBuffer((bytes,c)->{if(bytes==null||bytes.length!=460800)throw new AssertionError("Preview callback size differs");callbacks++;if(callbacks==1)System.err.println("SDCAMERA_PROBE=callback|bytes="+bytes.length);c.addCallbackBuffer(bytes);if(callbacks>=5&&!captured){captured=true;new Handler().postDelayed(()->take(),3500);}});camera.addCallbackBuffer(new byte[460800]);camera.addCallbackBuffer(new byte[460800]);camera.startPreview();if(!camera.previewEnabled())throw new AssertionError("Preview state differs");System.err.println("SDCAMERA_PROBE=preview_started|size=640x480");}catch(java.io.IOException failure){throw new AssertionError(failure);}}
 private void take(){camera.takePicture(()->System.err.println("SDCAMERA_PROBE=shutter"),null,(bytes,c)->{if(bytes==null||bytes.length<100||bytes[0]!=(byte)0xff||bytes[1]!=(byte)0xd8)throw new AssertionError("JPEG signature missing");BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(options.outWidth!=640||options.outHeight!=480)throw new AssertionError("JPEG dimensions differ");System.err.println("SDCAMERA_PROBE=jpeg_passed|bytes="+bytes.length+"|size="+options.outWidth+"x"+options.outHeight+"|callbacks="+callbacks);c.startPreview();new Handler().postDelayed(()->{camera.setPreviewCallbackWithBuffer(null);camera.stopPreview();camera.release();camera=null;System.err.println("SDCAMERA_PROBE=released|success=true");},500);});}
 @Override public void surfaceDestroyed(SurfaceHolder holder){ready=false;if(camera!=null){camera.setPreviewCallbackWithBuffer(null);camera.release();camera=null;}}
 @Override public void surfaceChanged(SurfaceHolder holder,int format,int width,int height){}
 @Override protected void onDestroy(){if(camera!=null){camera.setPreviewCallbackWithBuffer(null);camera.release();camera=null;}super.onDestroy();}
}
